    onChange?: (markdown: string) => void
    onError?: (payload: { error: string; source: string }) => void
    overlayContainer?: HTMLElement | null
    plugins?: StubPlugin[]
    readOnly?: boolean
    suppressHtmlProcessing?: boolean
}

interface StubEditorHandle {
    getMarkdown: () => string
    getSelectionMarkdown: () => string
