        fireEvent.paste(screen.getByRole('textbox'), {clipboardData: {getData: (type: string) => type === 'text/markdown' ? '**Markdown**' : 'Plain text'}})

        expect(screen.getByRole('textbox')).toHaveValue('**Markdown**')
